typedef struct PathMoverVars {
    u8 pad_00[0x20];
    s32 unk20;                     /* 0x20 */
    s16 unk24;                     /* 0x24 */
    u8 pad_26[0x2];
    u8 unk28;                      /* 0x28 */
    u8 pad_29[0x15];
    s16 unk3E;                     /* 0x3E */
    u8 pad_40[0x20];
    u8 carry[0x40];                /* 0x60: update_entity_matrix builds here */
    s8 start_end;                  /* 0xA0: signed in the matched code */
    u8 pad_A1[0x3];
    f32 t;                         /* 0xA4 */
    f32 speed;                     /* 0xA8 */
    f32 target_speed;              /* 0xAC */
    f32 travel_time;               /* 0xB0 */
    s32 path;                      /* 0xB4 */
    s16 retrigger;                 /* 0xB8 */
    s16 wait;                      /* 0xBA */
    f32 rise;                      /* 0xBC */
    s32 trigger;                   /* 0xC0 */
    s32 voice;                     /* 0xC4 */
    s32 silent;                    /* 0xC8 */
    s32 show_volume;               /* 0xCC */
    f32 ease[3];                   /* 0xD0 */
} PathMoverVars;

/* platform update: rides a keyframe path, switches direction on hits, eases its position toward the path point */
extern Hero hero __asm__("D_0013F450");
extern s32 level_moby_killed[][0x40] __asm__("D_0014C290");

void KeyframePlatformUpdate(unsigned char *moby) {
    enum {
        PATH_MOVER_COMMAND_WAIT_AT_LAST_POINT = 0,
        PATH_MOVER_COMMAND_WAIT_AT_FIRST_POINT = 1,
        PATH_MOVER_COMMAND_TRAVERSE_PATH = 2
    };
    typedef int VecQuad __attribute__((mode(TI), aligned(16)));
        typedef struct {
        s32 count;
        u8 pad4[0xC];
        Vec4 points[1];
    } MoverPath;
    typedef struct {
        u32 handle;
        u8 state;
        u8 flags;
        u8 pad6[2];
        void *definition;
        u16 sound_index;
        s16 linked_index;
        s32 volume;
        s32 pitch_bend;
        struct Moby *owner;
        s32 owner_context;
        Vec4 position;
        Vec4 position_offset;
        s32 history_position;
        u8 history_storage[0x2C];
    } VoiceSlot;
    typedef struct {
        u8 header[0x70];
        VoiceSlot voice;
    } VoicePoolWindow;
    struct Moby *m = (struct Moby *)moby;
    PathMoverVars *vars = (PathMoverVars *)m->pvars;
    MoverPath *path;
    Vec4 orig;
    Vec4 delta;
    Vec4 step;
    Vec4 goal;
    s32 on = 0;

    if (vars->path == -1) {
        return;
    }
    path = (MoverPath *)oltanis_paths[vars->path];
    if (vars->show_volume != -1) {
        if (is_point_inside_clip_volume(&hero.motion.pos, vars->show_volume) == 0) {
            m->update_dist = 0xFF;
            m->collision = 0;
            m->flags |= 0x41;
            return;
        }
        if (vars->show_volume != -1 && is_point_inside_clip_volume(&hero.motion.pos, vars->show_volume)) {
            m->flags &= 0xFFBE;
            m->collision = m->pclass->collision;
            vars->show_volume = -1;
        }
    }
    {
        u16 id;

        if (vars->trigger == -1 || is_point_inside_clip_volume(&hero.motion.pos, vars->trigger) ||
            oltanis_collected_flags_base.collected[(s16)(id = m->save_id)] != 0 ||
            (level_moby_killed[g_current_level_index_m][(s16)id >> 5] >> (id & 0x1F)) & 1) {
            if (vars->trigger != -1) {
                level_moby_killed[g_current_level_index_m][(s16)m->save_id >> 5] |= 1 << (m->save_id & 0x1F);
                oltanis_moby_killed_bits[(s16)m->save_id >> 5] |= 1 << (m->save_id & 0x1F);
                vars->trigger = -1;
            }
            on = 1;
        }
    }
    qcopy(&orig, &m->pos);
    FastDecTimer((void *)&vars->wait);
    if (m->state == 0) {
        f32 t;
        Vec4 *points;

        vars->unk28 = 4;
        vars->unk3E = 5;
        vars->unk20 = 0;
        vars->unk24 = 0;
        t = 0.0f;
        if ((m->command = vars->start_end) == 0) {
            t = 1.0f;
        }
        vars->t = t;
        points = path->points;
        /* the unsigned index keeps retail's (count - 1) << 4; a signed one folds the -1 into the pointer */
        qcopy(&m->pos, truncate_float_to_s32_r(t) ? &points[(u32)(path->count - 1)] : points);
        vars->wait = 0;
        vars->speed = 0.0f;
        vars->rise = 0.0f;
        m->state = 1;
        m->update_dist = 0xFF;
        m->draw_dist = 0xFF;
        vars->voice = -1;
    }
    switch (m->command) {
    case PATH_MOVER_COMMAND_WAIT_AT_LAST_POINT:
        if (on) {
            f32 far;

            if ((vars->retrigger != 0 && is_hero_on_moby(m)) ||
                (far = FastVecDist(&hero.motion.pos, &path->points[path->count - 1]),
                 FastVecDist(&hero.motion.pos, &path->points[0]) < far)) {
                m->command = 2;
                vars->target_speed = -1.0f / multiply_global_factor(vars->travel_time * 60.0f);
                vars->retrigger = 0;
            }
        }
        break;
    case PATH_MOVER_COMMAND_WAIT_AT_FIRST_POINT:
        if (on) {
            f32 near;

            if ((vars->retrigger != 0 && is_hero_on_moby(m)) ||
                (near = FastVecDist(&hero.motion.pos, &path->points[0]),
                 FastVecDist(&hero.motion.pos, &path->points[path->count - 1]) < near)) {
                m->command = 2;
                vars->target_speed = 1.0f / multiply_global_factor(vars->travel_time * 60.0f);
                vars->retrigger = 0;
            }
        }
        break;
    case PATH_MOVER_COMMAND_TRAVERSE_PATH:
        if (vars->silent == 0 && is_hero_on_moby(m)) {
            hero.jump_lock_timer = 4;
            hero.unk1F4 = 4;
        }
        if (vars->wait != 0 ||
            (vars->rise < 0.0f && vec_distance_xy(&m->pos, &hero.motion.pos) < 2.0f &&
             FastAbsF(hero.motion.pos.f[2] - m->pos.z) < 4.0f &&
             m->pos.z - hero.motion.pos.f[2] > 1.0f)) {
            s32 voice;

            if (vars->wait == 0) {
                vars->wait = scale_ticks(30);
            }
            voice = vars->voice;
            vars->speed = 0.0f;
            if (voice != -1) {
                VoicePoolWindow *slot = (VoicePoolWindow *)((u8 *)(hero_globals_base + 0x1D) + voice * 0x70);

                if (slot->voice.owner == m && slot->voice.state != 0) {
                    Sound_StopSlot(voice);
                }
            }
            vars->voice = -1;
        } else {
            s32 i;
            f32 frac;
            f32 fi;
            Vec4 *from;

            if (!Sound_IsPlaying(m, vars->voice)) {
                vars->voice = Moby_PlaySound(0, 4, (int)m);
            }
            vars->speed += vars->target_speed * g_frame_time;
            if (FastAbsF(vars->speed) > FastAbsF(vars->target_speed)) {
                vars->speed = vars->target_speed;
            }
            vars->t = vars->t + vars->speed;
            if (0.5f < FastAbsF(vars->t - 0.5f)) {
                s32 voice;

                if (0.0f < vars->target_speed) {
                    m->command = 0;
                    vars->t = 1.0f;
                } else {
                    m->command = 1;
                    vars->t = 0.0f;
                }
                vars->speed = 0.0f;
                vars->wait = scale_ticks(15);
                voice = vars->voice;
                if (voice != -1) {
                    VoicePoolWindow *slot = (VoicePoolWindow *)((u8 *)(hero_globals_base + 0x1D) + voice * 0x70);

                    if (slot->voice.owner == m && slot->voice.state != 0) {
                        Sound_StopSlot(voice);
                    }
                }
                vars->voice = -1;
            }
            frac = IntToFloat(path->count - 1);
            i = truncate_float_to_s32_r(frac * vars->t);
            frac = IntToFloat(path->count - 1);
            fi = IntToFloat(i);
            frac *= vars->t;
            frac -= fi;
            if (i == path->count - 1) {
                qcopy(&goal, &path->points[i]);
            } else {
                from = &path->points[i];
                FastVecSub(step.f, path->points[i + 1].f, from->f);
                FastVecScale(step.f, step.f, frac);
                FastVecAdd(goal.f, step.f, from->f);
            }
            Spring(&m->pos.x, &vars->ease[0], goal.f[0], 0.005f, 0.2f, 0.0f);
            Spring(&m->pos.y, &vars->ease[1], goal.f[1], 0.005f, 0.2f, 0.0f);
            Spring(&m->pos.z, &vars->ease[2], goal.f[2], 0.005f, 0.2f, 0.0f);
            vars->rise = m->pos.z - orig.f[2];
        }
        break;
    }
    if (m->command != 2) {
        ease_path_mover_to_endpoint((char *)m);
    }
    FastVecSub(delta.f, &m->pos.x, orig.f);
    update_entity_matrix(vars->carry, delta.f, &m->rot.x, &m->rot.x);
    if (!is_hero_on_moby(m)) {
        if (2.0f < vec_distance_xy(&m->pos, &hero.motion.pos)) {
            if (vars->wait == 0) {
                vars->retrigger = 1;
            }
        }
    }
}
extern float Spring(float *p, float *v, float t, float u1, float u2, float eps);
extern int *oltanis_paths[];

// Pick a keyframe vector from the moby's table and ease the moby position toward it per axis.
void ease_path_mover_to_endpoint(char *moby) {
    struct PathMoverVars *data = (struct PathMoverVars *)((Moby *)moby)->pvars;
    float v[4];
    char *src;
    int *tab;
    tab = oltanis_paths[data->path];
    if (data->t > 0.5f) {
        src = (char *)(tab[0] * 16 + (int)tab);
        qcopy(v, src);
    } else {
        src = (char *)tab + 0x10;
        qcopy(v, src);
    }
    Spring((float *)(moby + 0x10), &data->ease[0], v[0], 0.005f, 0.2f, 0.0f);
    Spring((float *)(moby + 0x14), &data->ease[1], v[1], 0.005f, 0.2f, 0.0f);
    Spring((float *)(moby + 0x18), &data->ease[2], v[2], 0.005f, 0.2f, 0.0f);
}
