void draw_blarg_heavy_interceptor_camera_facing_glow(char *moby) {
    struct HeavyInterceptorVars *d = (struct HeavyInterceptorVars *)((struct Moby *)moby)->pvars;
    float glow_quad_transform[4][4];
    float glow_position_offset[4];
    Pk_2ae0a8 pk;
    float glow_to_camera_vector[4];
    float camera_facing_angles[4];
    char *base;
    char *v;
    char *q;
    float f;
    int i;
    long r;
    qcopy(glow_quad_transform[3], &d->beam_origin);
    glow_quad_transform[3][3] = 1.0f;
    FastVecScale(glow_position_offset, d->ring_basis, *(float *)&interceptor_glow_forward_offset);
    FastVecAdd(glow_quad_transform[3], glow_quad_transform[3], glow_position_offset);
    r = GetEffectTex(0xB);
    pk.b = r;
    pk.c = 0xFF9000000260L;
    pk.d = 0x8000000048L;
    pk.a = 0;
    VU1_addGSregister(0x47, 0x51001);
    FastVecSub(glow_to_camera_vector, oltanis_camera_pos, glow_quad_transform[3]);
    f = fast_atan2(glow_to_camera_vector[0], glow_to_camera_vector[1]);
    camera_facing_angles[2] = f;
    f = fast_atan2(vec_length_xy(glow_to_camera_vector), glow_to_camera_vector[2]);
    camera_facing_angles[1] = -f;
    camera_facing_angles[0] = 0.0f;
    euler_rotation_basis(glow_quad_transform, camera_facing_angles);
    pk.uv[0] = 1.0f;
    pk.uv[1] = 1.0f;
    pk.uv[2] = 0.0f;
    pk.uv[3] = 1.0f;
    pk.uv[5] = 0.0f;
    pk.uv[6] = 0.0f;
    pk.uv[7] = 0.0f;
    pk.uv[4] = 1.0f;
    if (d->locked_on != 0) {
        pk.col[3] = 0x7F40407F;
        pk.col[2] = 0x7F40407F;
        pk.col[1] = 0x7F40407F;
        pk.col[0] = 0x7F40407F;
    } else {
        pk.col[3] = 0x7F7F7F7F;
        pk.col[2] = 0x7F7F7F7F;
        pk.col[1] = 0x7F7F7F7F;
        pk.col[0] = 0x7F7F7F7F;
    }
    base = (char *)pk.m;
    v = base;
    q = interceptor_quad_corners;
    for (i = 3; i >= 0; i--) {
        FastVecScale(v, q, *(float *)&interceptor_glow_size);
        q += 0x10;
        transform_vector(v, v, glow_quad_transform);
        v += 0x10;
    }
    draw_world_quad(base, 0, 0);
}
